package com.idfc.ai.runbook.diff; import com.fasterxml.jackson.databind.*; import java.security.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public class SectionFingerprintService { private final ObjectMapper mapper; public SectionFingerprintService(ObjectMapper m){mapper=m;} public Map<String,String> fingerprints(JsonNode n){Map<String,String> out=new TreeMap<>();n.fieldNames().forEachRemaining(k->{if(!k.equals("pipeline"))out.put(k,hash(n.path(k)));});return out;} private String hash(JsonNode n){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(mapper.writeValueAsBytes(n)));}catch(Exception e){throw new IllegalStateException(e);}} }
